package io.github.diodeme.ji.spring;

import java.nio.file.Path;
import org.springframework.boot.context.properties.ConfigurationProperties;

/** Spring-bound Local Host properties converted to the same product configuration keys as CLI. */
@ConfigurationProperties("ji.host")
public record JiHostProperties(
        boolean enabled,
        Path dataDirectory,
        Path workspaceRoot,
        String model,
        String baseUrl,
        int port) {
    public JiHostProperties {
        dataDirectory = dataDirectory == null ? Path.of(System.getProperty("user.home"), ".ji") : dataDirectory;
        workspaceRoot = workspaceRoot == null ? Path.of(".") : workspaceRoot;
        model = model == null ? "" : model;
        baseUrl = baseUrl == null ? "" : baseUrl;
        if (port < 0 || port > 65_535) throw new IllegalArgumentException("ji.host.port is out of range");
    }
}
